"""跨页面导航 — 从任意页面到达目标页面。

提供游戏层的核心导航能力: ``ensure_page(ctx, PageName.目标)``。

UNKNOWN 与孤岛页是一等状态：识别不出页面、或页面在导航图上没有出口时，
不会立刻抛错中止任务，而是先走 :func:`escape` 的「返回箭头 → 清弹窗 → 退避」
阶梯，恢复出可导航页面后重新做 BFS 规划；整个过程受 :data:`MAX_ESCAPE_ATTEMPTS`
预算约束，避免无限重试。

每一步的页面/动作都会记入 :class:`_NavWatchdog`：同页同动作 3 次、连续 12 步
停在同页、连续 5 次动作没改变页面，或 12 步仍未到达目标时，抛带页面轨迹的
:class:`~autowsgr.infra.exceptions.PageDriftError` 立即中止，而不是把 20 步预算
喂给无效点击后只报一句「步数超限」。页面识别在所有重试/全量兜底后最高分仍
低于 0.4 时，改抛 :class:`~autowsgr.infra.exceptions.UIVersionError`（4.3）。
"""

from __future__ import annotations

import time
from typing import TYPE_CHECKING

from autowsgr.infra.exceptions import PageDriftError, TaskStopRequested, UIVersionError
from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.navigation import find_path
from autowsgr.ui.page import dump_page_scores, format_page_scores, get_current_page
from autowsgr.ui.utils import NavigationError, PageNotRecognizedError


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext
    from autowsgr.ui.stack import UIStack

_log = get_logger('ops')

# ═══════════════════════════════════════════════════════════════════════════════
# 常量
# ═══════════════════════════════════════════════════════════════════════════════

MAX_IDENTIFY_ATTEMPTS: int = 5
"""页面识别最大尝试次数。"""

IDENTIFY_INTERVAL: float = 1.0
"""页面识别重试间隔 (秒)。"""

MAX_ESCAPE_ATTEMPTS: int = 3
"""UNKNOWN / 孤岛页的最大出逃重规划次数 (恢复预算)。

每次出逃会跑完整的三级阶梯，之后重新识别 + BFS。预算用尽即抛明确错误，
不允许 ``ensure_page`` 无限循环。
"""

ESCAPE_BACKOFF: float = 2.0
"""出逃阶梯最后一级的退避时长 (秒)，给加载 / 动画一个完整窗口。"""

# ── 看门狗阈值（单一数据源） ──
# 旧的 _detect_stall 已并入 _NavWatchdog，不再维护第二套打转判定。
WATCHDOG_TRAIL_LIMIT: int = 15
"""页面/动作轨迹只保留最近 15 步，防止长任务累积内存。"""

WATCHDOG_SAME_ACTION_LIMIT: int = 3
"""同一页面同一动作连续执行次数上限。"""

WATCHDOG_SAME_PAGE_LIMIT: int = 12
"""连续 12 步仍停在同一页面 → 卡死。"""

WATCHDOG_MAX_STEPS: int = 12
"""连续 12 步未到达目标 → 卡死（兜底，覆盖 A↔B 振荡等换页但不前进的场景）。"""

WATCHDOG_FAILURE_LIMIT: int = 5
"""连续动作没有改变页面（点击没反应 / 重试）次数上限。"""

MAX_NAV_STEPS: int = 20
"""导航循环硬上限；正常情况下看门狗会在 12 步前先触发。"""


# ═══════════════════════════════════════════════════════════════════════════════
# 页面识别
# ═══════════════════════════════════════════════════════════════════════════════


def identify_current_page(
    ctx: GameContext,
    candidates: set[str] | None = None,
    *,
    attempts: int = MAX_IDENTIFY_ATTEMPTS,
) -> str | None:
    """截图并识别当前页面。

    尝试多次截图以应对动画或加载中的情况。候选集识别重试耗尽后
    追加一轮全量识别兜底 —— 栈漂移可能把真实页面排除在候选之外。

    Parameters
    ----------
    candidates:
        候选页面名集合。``None`` 时评估全部注册页;导航过程中由
        :func:`_goto_page` 从 :attr:`GameContext.ui_stack` 计算并传入,
        以收缩搜索空间。
    attempts:
        识别重试次数上限。出逃阶梯用较短预算 (2 次)，避免一次恢复
        就要等满 5 秒;正常导航保持原默认值。

    Returns
    -------
    str | None
        当前页面名称，无法识别返回 ``None``。

    Raises
    ------
    UIVersionError
        重试/全量兜底后最高分仍低于 ``UI_VERSION_MAX_SCORE``。
    TaskStopRequested
        识别过程中用户请求停止。
    """
    ctrl = ctx.ctrl
    total_attempts = max(1, attempts)
    for attempt in range(total_attempts):
        # 识别本身最长要 5 次 × 1 秒；不在这里查停止的话，用户点了停止
        # 还要等这 5 秒耗尽，然后打出一条误导性的「无法识别当前页面」ERROR。
        if ctx.stop_event.is_set():
            raise TaskStopRequested('页面识别')
        screen = ctrl.screenshot()
        # 最后一次全量尝试才允许把「整体低分」升级为 UIVersionError：
        # 前几次低分可能只是加载/转场帧，不能一上来就判定模板失效。
        page = get_current_page(
            screen,
            candidates=candidates,
            raise_on_total_failure=(
                candidates is None and attempt == total_attempts - 1
            ),
        )
        if page is not None:
            return page
        _log.debug(
            '[OPS] 页面识别失败 (第 {} 次尝试), 等待重试',
            attempt + 1,
        )
        time.sleep(IDENTIFY_INTERVAL)

    if candidates is not None:
        # 候选耗尽:降级全量识别一轮(候选集可能因栈漂移漏掉真实页面)。
        # 这也是把「候选全灭且最高分 < 0.4」升级为 UIVersionError 的收口点。
        screen = ctrl.screenshot()
        page = get_current_page(screen, raise_on_total_failure=True)
        if page is not None:
            _log.warning('[OPS] 候选识别失败, 全量兜底命中: {}', page)
            return page

    # 全量也失败 —— 打印各页面分数现场, 否则日志只有一句"无匹配", 无法区分
    # "某页 0.93 但没进候选" 与 "最高分只有 0.55 差一口气"。
    try:
        from autowsgr.ui.page import dump_page_scores

        rows = dump_page_scores(ctrl.screenshot())
        _log.warning(
            '[OPS] 识别失败取证 (分数降序): {}', format_page_scores(rows, top=6)
        )
    except Exception:  # pragma: no cover - 取证失败不影响主流程
        _log.opt(exception=True).debug('[OPS] 识别失败取证异常')
    return None


def _sync_ctx_page(ctx: GameContext, name: str) -> None:
    """把识别结果同步到 ``ctx.current_page`` 并推送 UI 状态（4.5）。

    ``current_page`` 是 deprecated 字段，仅供旧读者；前端自省走
    ``ctx.publish_ui_state(page=...)``，由 ``GameContext`` 做「只在变化时推」
    的去重。这里传的是**对账之后**的页面，导航栈与实际页面不会出现「页面
    已变、栈还是上一步」的错位。
    """
    try:
        ctx.current_page = PageName(name)
    except ValueError:
        ctx.current_page = None

    publish = getattr(ctx, 'publish_ui_state', None)
    if callable(publish):
        publish(page=name)


def _safe_screenshot(ctx: GameContext) -> np.ndarray | None:
    """取失败现场截图；设备已断时不要让取证异常盖住真正的导航错误。"""
    try:
        return ctx.ctrl.screenshot()
    except Exception:  # pragma: no cover - 设备异常只影响取证，不影响错误上抛
        _log.opt(exception=True).debug('[OPS] 失败现场截图异常')
        return None


class _NavWatchdog:
    """导航防呆看门狗：页面/动作轨迹 + 跨轮次卡死判定。

    旧 ``_detect_stall`` 的「同页 4 次 / 振荡窗口 4」已并入本类，看门狗成为
    唯一数据源。判定不是看单次超时，而是看**轮与轮之间**的模式：

    - 同一页面、同一动作连续 3 次；
    - 连续 12 步仍停在同一页面；
    - 连续 5 次动作后页面没变化（点击没反应 / 重试）；
    - 连续 12 步未到达目标（兜底，覆盖 A→B→A→B 这类换页但不前进的振荡）。

    轨迹只保留最近 :data:`WATCHDOG_TRAIL_LIMIT` 步。``escape`` 内部的
    返回键 / 清弹窗动作**不**记入这里：出逃重试不直接算失败，避免 4.2 的
    恢复阶梯把看门狗喂爆；出逃整体仍有 ``MAX_ESCAPE_ATTEMPTS`` 硬预算。
    """

    def __init__(self, target: str) -> None:
        self.target = target
        self._trail: list[tuple[float, str, str]] = []  # (monotonic, 页面, 动作名)
        self._last_page: str | None = None
        self._pending_action = False
        self._steps_on_page = 0
        self._failures = 0
        self._total_steps = 0

    @property
    def page_trail(self) -> list[str]:
        return [page for _, page, _ in self._trail]

    @property
    def action_trail(self) -> list[str]:
        return [action for _, _, action in self._trail]

    def observe(self, page: str) -> None:
        """消费上一步动作，更新「同页 / 连败」计数；必须在识别后调用。"""
        if self._pending_action:
            if page == self._last_page:
                # 动作执行后页面没变：点击没反应 / 重试。
                self._steps_on_page += 1
                self._failures += 1
            else:
                self._steps_on_page = 0
                self._failures = 0
            self._pending_action = False
        elif page != self._last_page:
            # 首次识别，或出逃后重新规划到新页面：不继承上一页的计数。
            self._steps_on_page = 0
            self._failures = 0
        self._last_page = page

    def record(self, page: str, action: str) -> None:
        """记录一步点击后的 (时间, 页面, 动作名)，只保留最近 15 步。"""
        self._trail.append((time.monotonic(), page, action))
        if len(self._trail) > WATCHDOG_TRAIL_LIMIT:
            del self._trail[0]
        self._total_steps += 1
        self._pending_action = True

    def check(self, current: str) -> str | None:
        """返回命中的卡死原因；``None`` 表示可以继续导航。"""
        if self._failures >= WATCHDOG_FAILURE_LIMIT:
            return (
                f'连续 {WATCHDOG_FAILURE_LIMIT} 次动作没有改变页面 '
                f'(当前: "{current}")'
            )

        if self._steps_on_page >= WATCHDOG_SAME_PAGE_LIMIT:
            return f'连续 {WATCHDOG_SAME_PAGE_LIMIT} 步停在 "{current}"'

        same_action = self._same_action_streak(current)
        if same_action is not None:
            page, action = same_action
            return (
                f'同一页面同一动作连续执行 {WATCHDOG_SAME_ACTION_LIMIT} 次: '
                f'"{page}" / {action}'
            )

        oscillated = self._oscillation(current)
        if oscillated is not None:
            return f'导航来回振荡: {oscillated}'

        if self._total_steps >= WATCHDOG_MAX_STEPS:
            return f'连续 {WATCHDOG_MAX_STEPS} 步未到达目标 "{self.target}"'

        return None

    def _same_action_streak(self, current: str) -> tuple[str, str] | None:
        """连续 3 步的 (页面, 动作) 完全相同，且当前仍在该页。"""
        limit = WATCHDOG_SAME_ACTION_LIMIT
        if len(self._trail) < limit:
            return None
        tail = self._trail[-limit:]
        page, action = tail[0][1], tail[0][2]
        # 当前页必须还是动作的出发页：否则第 3 次动作已经生效，不能算卡死。
        if current != page:
            return None
        if all(
            entry_page == page and entry_action == action
            for _, entry_page, entry_action in tail
        ):
            return page, action
        return None

    def _oscillation(self, current: str) -> str | None:
        """检测 A→B→A→B（或更长周期）的来回振荡。

        在最近 4..12 步的偶数窗口里找「前后两半完全相同」的页面序列；
        ``tail[0] != tail[1]`` 排除全同页（那由同页规则负责）。
        """
        sequence = [*self.page_trail, current]
        max_window = min(WATCHDOG_MAX_STEPS, len(sequence))
        for window in range(4, max_window + 1, 2):
            tail = sequence[-window:]
            half = window // 2
            if tail[:half] == tail[half:] and tail[0] != tail[1]:
                return ' → '.join(tail)
        return None


def _raise_stuck(
    ctx: GameContext,
    watchdog: _NavWatchdog,
    reason: str,
) -> None:
    """把看门狗命中结果升级为带轨迹的 :class:`PageDriftError` 并立即抛出。"""
    _log.error(
        '[OPS] 看门狗判定导航卡死(页面漂移): {} (目标: {}，最近页面: {})',
        reason,
        watchdog.target,
        ' → '.join(watchdog.page_trail) or '无',
    )
    raise PageDriftError(
        reason,
        target=watchdog.target,
        page_trail=watchdog.page_trail,
        action_trail=watchdog.action_trail,
        screen=_safe_screenshot(ctx),
    )


# ═══════════════════════════════════════════════════════════════════════════════
# 导航函数
# ═══════════════════════════════════════════════════════════════════════════════


class _UnreachablePageError(NavigationError):
    """当前页是孤岛页，或目标页在导航图上不可达。

    与 :class:`PageNotRecognizedError` 的区别：页面**认得出**，但站在导航图
    外面 (没有出边) 或目标没有入边，BFS 必然返回 ``None``。这类失败同样
    不能原地重试，必须交给 :func:`escape` 出逃后重规划。
    """

    def __init__(
        self,
        current: str,
        target: str,
        *,
        screen: np.ndarray | None = None,
    ) -> None:
        self.current = current
        self.target = target
        super().__init__(
            f"导航图不可达: 当前页 '{current}' 是孤岛页面，"
            f"或目标页 '{target}' 在图上没有入边",
            screen=screen,
        )


def _page_label(page: str) -> str:
    """把 ``PageName`` 归一化成中文页面名，用于日志与卡死轨迹。"""
    return str(getattr(page, 'value', page))


def _goto_page(
    ctx: GameContext,
    target: str,
    *,
    watchdog: _NavWatchdog | None = None,
) -> None:
    """从当前页面导航到目标页面。

    采用逐步重规划策略 (Step-by-Step Re-planning):
    1. 识别当前页面, 并用 ``ctx.ui_stack.observe`` 对账
    2. 看门狗消费上一步结果并判定是否卡死
    3. BFS 查找路径，声明意图 (``ui_stack.push``) 后执行第一步
    4. 记录 (时间, 出发页, 动作名) 后循环回到 1，直到到达目标

    这允许处理不确定的导航动作 (如: build -> sidebar | main)。

    Parameters
    ----------
    watchdog:
        由 :func:`ensure_page` 创建并跨出逃重试复用，使「出逃后仍在同一页
        打转」也能被 12 步规则捕获。直接调用时退化为单次导航的局部看门狗。

    Raises
    ------
    PageDriftError
        同页同动作 3 次 / 同页 12 步 / 连败 5 次 / 12 步未达目标。
    NavigationError
        无法识别当前页面、找不到路径或步数超限。
    """
    max_steps = MAX_NAV_STEPS
    stack = ctx.ui_stack
    # 候选集:首轮全表扫描(真不知在哪);每步由栈给出
    # {current} + neighbors(current) + {parent} + {target} + neighbors(target),
    # 相比纯邻域机制多纳入 parent, 覆盖回退时序与无入边叶子页 (CHOOSE_SHIP 等)。
    candidates: set[str] | None = None
    watchdog = watchdog or _NavWatchdog(_page_label(target))

    for step in range(max_steps):
        # 0. 停止检查 —— 导航最长可跑 20 步（每步识别最多 5 秒），
        #    不在这里查停止，用户点了停止还要等它走完/失败才响应。
        if ctx.stop_event.is_set():
            raise TaskStopRequested('导航')

        # 1. 识别 + 对账
        current = identify_current_page(ctx, candidates=candidates)
        if current is None:
            raise PageNotRecognizedError(
                f'无法识别当前页面，导航中止 (目标: {target})',
                screen=ctx.ctrl.screenshot(),
            )
        stack.observe(current)

        # 1b. 消费漂移信号: candidates 可能给出"自信但错误"的答案
        #     (例: 活动页 0.868 命中准备页标题栏, 而准备页未进候选)。
        #     observe 只打 WARN 不改栈, 这里用全量识别复核, 以全量为准并清标记。
        if stack.drifted:
            current = _reconcile_drift(ctx, stack, current, target)

        _sync_ctx_page(ctx, current)

        # 2. 检查 (先判到达: 到达即成功, 不受看门狗影响)
        if current == target:
            _log.info('[OPS] 已在目标页面: {}', target)
            return

        # 2b. 看门狗：先消费上一步结果，再判定是否卡死。
        #     旧 _detect_stall 的振荡检测已并入 watchdog._oscillation。
        page = _page_label(current)
        watchdog.observe(page)
        reason = watchdog.check(page)
        if reason is not None:
            _raise_stuck(ctx, watchdog, reason)

        # 3. 寻路
        path = find_path(current, target)
        if path is None:
            # 认得出页面 ≠ 走得到。孤岛页 (无出边) / 目标无入边时 BFS 必空，
            # 交给 ensure_page 出逃后重规划，而不是原地重试或直接中止任务。
            raise _UnreachablePageError(
                current,
                target,
                screen=_safe_screenshot(ctx),
            )

        if not path:  # Should be covered by current == target, but safe check
            _log.info('[OPS] 已在目标页面: {}', target)
            return

        # 4. 执行一步:先声明意图(下一轮识别的 observe 会纠正),
        #    动作失败未到达时, 识别到 parent 会被 pop 回收
        edge = path[0]
        action_name = edge.description or f'{edge.source}→{edge.target}'
        _log.debug(
            '[OPS] 步骤 {} (总限 {}，已记录 {} 步): {} → {} ({})',
            step + 1,
            max_steps,
            len(watchdog.page_trail),
            edge.source,
            edge.target,
            edge.description,
        )
        stack.push(edge.target)
        try:
            edge.action(ctx)
        finally:
            # 「每一步点击后」记录 (时间, 出发页, 动作名)。动作抛错也记，
            # 否则异常路径会绕过看门狗，ensure_page 出逃重试时看不到这次失败。
            watchdog.record(_page_label(current), action_name)
        candidates = stack.candidates(target) or None

    _raise_stuck(
        ctx,
        watchdog,
        f'导航步数超过硬上限 ({max_steps})',
    )


def _reconcile_drift(
    ctx: GameContext,
    stack: UIStack,
    current: str,
    target: str,
) -> str:
    """候选识别与栈预测冲突时的复核与校正。

    ``UIStack.observe`` 发现识别结果落在"当前页邻域之外"时只置 ``drifted``
    并打一条 WARN —— 该信号此前全仓无人消费, 等于空转。这里用全量识别复核:

    - 全量结果 ≠ 候选结果 → 候选识别被邻域内的高分误命中带偏, 以全量为准;
    - 全量结果 = 候选结果 → 是**栈**记错了, 用实际页重建栈顶。

    两种情况都以 ``stack.replace(...)`` 收尾, 顺带清掉漂移标记,
    避免每步都重复复核。
    """
    screen = ctx.ctrl.screenshot()
    verified = get_current_page(screen)  # 全量, 不带候选约束
    resolved = verified or current

    if verified is None:
        # 3.4 之后"全量识别失败"还包括 margin/近失判 UNKNOWN 的歧义帧 ——
        # 这不等于"与候选一致", 不能打误导性的确认日志。
        _log.warning('[OPS] 栈漂移复核: 全量识别亦为 UNKNOWN, 沿用候选结果 {}', current)
    elif verified != current:
        _log.warning('[OPS] 栈漂移复核: 候选={} 全量={}, 以全量为准', current, verified)
        try:
            rows = dump_page_scores(screen)
            _log.warning('[OPS] 分数现场: {}', format_page_scores(rows, top=5))
        except Exception:  # pragma: no cover - 取证失败不影响主流程
            pass
    else:
        _log.warning('[OPS] 栈漂移已确认: 实际页={} (与全量一致), 重建栈顶', current)

    stack.replace(resolved)
    return resolved


def _try_dismiss_popup(ctx: GameContext) -> bool:
    """尝试点掉会整屏遮挡识别的确认类弹窗, 返回是否点掉了什么。

    确认弹窗 (网络重连、资源不足、任务提示) 会把页面签名整个盖住,
    此时候选识别和 checker 同时失效 —— 表现就是"突然什么都认不出"。
    先清弹窗再谈重建栈, 成本最低。
    """
    try:
        from autowsgr.ui.utils import confirm_operation

        return confirm_operation(ctx.ctrl, must_confirm=False, timeout=0.0)
    except Exception:  # pragma: no cover - 清理失败不应中断恢复流程
        _log.opt(exception=True).debug('[OPS] 弹窗清理异常')
        return False


def _try_press_back(ctx: GameContext) -> bool:
    """点游戏内的「◁」返回箭头，返回是否点到了。

    **不是安卓物理返回键。** 这两个东西常被混为一谈：
    物理键（KEYCODE_BACK）在游戏里只会弹「是否退出游戏」，而这里的模板
    ``common/back_*.png`` 是 UI 上真实渲染的那个圆角箭头。

    实测依据（2026-10-26）：
    - 出征准备页命中 ``back_1`` 置信度 0.972，中心 (43, 40)；
    - 点击后画面切到 10-1 地图页，**没有出现退出确认弹窗**；
    - 14 张截图横扫：有箭头的页面 ≥0.887，无箭头的战斗结果页 ≤0.739，
      0.85 的阈值落在空档里，零误判。

    因此用**模板命中的真实坐标**点击，而不是固定 ``(0.022, 0.058)``——
    不同页面的箭头位置有细微差异。

    注意：它执行的是「回上一页」，效果取决于当前在哪（准备页→地图页→主页面），
    连点会一路退回主页面、丢掉上下文。调用方只应在「认不出页面」时点一次。
    """
    try:
        from autowsgr.image_resources import Templates
        from autowsgr.vision import ImageChecker

        screen = ctx.ctrl.screenshot()
        detail = ImageChecker.find_any(screen, Templates.BackButton.all(), confidence=0.85)
        if detail is None:
            return False
        _log.info(
            '[OPS] 恢复: 命中返回箭头 {} ({:.3f}) @ ({:.3f}, {:.3f})',
            detail.template_name,
            detail.confidence,
            *detail.center,
        )
        ctx.ctrl.click(*detail.center)
        time.sleep(0.6)
        return True
    except Exception:  # pragma: no cover - 恢复动作失败不应中断流程
        _log.opt(exception=True).debug('[OPS] 返回键恢复异常')
        return False


def _try_dismiss_network_error(ctx: GameContext) -> bool:
    """处理网络类错误弹窗，返回是否点掉了什么。

    模板 ``error/*.png`` 从 classic 迁过来后一直没接线——R03 的触发条件里
    明写「网络重连弹窗」，正是「突然什么都认不出」的常见成因。

    只自动点 **「重新连接」**。异地登录 / 顶号类弹窗只记 warning 不点确认：
    那涉及账号层面的决定（要不要顶掉另一台设备），不该由自动化替他做主。
    """
    try:
        from autowsgr.image_resources import Templates
        from autowsgr.vision import ImageChecker

        screen = ctx.ctrl.screenshot()

        detail = ImageChecker.find_best(
            screen, [Templates.Error.NETWORK_RETRY], confidence=0.85
        )
        if detail is not None:
            _log.warning('[OPS] 恢复: 检测到网络重连弹窗, 点击重连 ({:.3f})', detail.confidence)
            ctx.ctrl.click(*detail.center)
            time.sleep(0.8)
            return True

        for name in ('REMOTE_LOGIN', 'REMOTE_LOGIN_CONFIRM'):
            tmpl = getattr(Templates.Error, name, None)
            if tmpl is None:
                continue
            hit = ImageChecker.find_best(screen, [tmpl], confidence=0.85)
            if hit is not None:
                _log.warning(
                    '[OPS] 恢复: 检测到异地登录弹窗 ({} {:.3f})，'
                    '涉及账号决定，不自动确认——请人工处理',
                    name,
                    hit.confidence,
                )
                break
        return False
    except Exception:  # pragma: no cover
        _log.opt(exception=True).debug('[OPS] 网络弹窗清理异常')
        return False


def _try_dismiss_result_overlay(ctx: GameContext) -> bool:
    """点掉「点击继续。」类整屏结果页，返回是否点掉了什么。

    远征完成后的结算页没有任何页面签名（识别分数最高 ~0.67），也没有返回
    箭头/确认按钮，只认右下角那行 "点击继续。"。它一旦残留，出逃三级阶梯
    全部无效，任务会一路失败到 ``recover_to_main_or_restart`` 强制重启。
    """
    try:
        from autowsgr.image_resources import Templates
        from autowsgr.vision import ImageChecker

        detail = ImageChecker.find_any(
            ctx.ctrl.screenshot(),
            [Templates.Symbol.EXPEDITION_CONTINUE],
            confidence=0.85,
        )
        if detail is None:
            return False
        _log.info('[OPS] 恢复: 检测到远征结果页, 点击继续 ({:.3f})', detail.confidence)
        ctx.ctrl.click(*detail.center)
        time.sleep(0.8)
        return True
    except Exception:  # pragma: no cover - 清理失败不应中断恢复流程
        _log.opt(exception=True).debug('[OPS] 结果页清理异常')
        return False


def _probe_page(ctx: GameContext, *, attempts: int = 2) -> str | None:
    """出逃后重新识别当前页面，用较短预算避免一次恢复等满 5 秒。

    出逃探测**不**让 UIVersionError 打断恢复：2 秒窗口内的低分更可能是
    加载黑屏；这里把分级异常降级为 ``None``（本轮出逃未恢复），
    由 ``ensure_page`` 的既有预算决定是否继续。
    """
    try:
        return identify_current_page(ctx, candidates=None, attempts=attempts)
    except UIVersionError as error:
        _log.debug('[OPS] 出逃探测低分（不升级 UI 版本错误）: {}', error)
        return None


def _is_navigable(page: str | None, target: str | None) -> bool:
    """页面是否已恢复到「能规划到 target」的状态。

    仅仅识别成功不够：CHOOSE_SHIP 这类孤岛页认得出来，却没有出边，
    BFS 仍然返回 ``None``。出逃成功的判据必须是「可导航」，否则会
    把孤岛页当成恢复成功，白白消耗一轮预算。
    """
    if page is None:
        return False
    if target is None:
        return True
    return page == target or find_path(page, target) is not None


def _adopt_page(ctx: GameContext, page: str) -> None:
    """出逃成功后把页面同步到 ctx 与 UIStack，作为重新规划的基线。"""
    _sync_ctx_page(ctx, page)
    ctx.ui_stack.reset(page)


def escape(
    ctx: GameContext,
    target: str | None = None,
    *,
    reason: str = '',
    allow_back: bool = True,
) -> str | None:
    """UNKNOWN / 孤岛页出逃阶梯：返回箭头 → 清弹窗 → 退避。

    每级执行后都会重新识别；只有识别到**可导航到 target** 的页面才算
    出逃成功 (见 :func:`_is_navigable`)。成功时把 UIStack 重置为该页，
    让后续 BFS 从干净状态重新开始。

    Parameters
    ----------
    ctx:
        游戏上下文。
    target:
        导航目标页。给出时要求出逃后的页面在图上能到达它；``None`` 时
        只要求重新识别成功 (供其他调用方单独使用出逃阶梯)。
    reason:
        触发本次出逃的原因，写入日志便于回溯。
    allow_back:
        是否允许点「◁」返回箭头。UNKNOWN / 孤岛页必须允许 (这是最有效
        的一级)；已知页面但走不过去 (打转 / 步数超限) 时关闭，沿用
        「知道在哪却走不过去 → 回退只会更乱」的既有结论。

    Returns
    -------
    str | None
        出逃后可用于重新规划的页面名；三级阶梯用尽仍不可导航返回 ``None``。

    Raises
    ------
    TaskStopRequested
        用户在中途请求停止。
    """
    if ctx.stop_event.is_set():
        raise TaskStopRequested('出逃')

    _log.warning(
        '[OPS] {}，尝试出逃: {}',
        '检测到未知/孤岛页面' if allow_back else '导航受阻',
        reason or '当前页面无法规划路径',
    )

    # ① 返回箭头：UNKNOWN 时最有效。只点一次，避免一路退回主页面丢掉上下文。
    if allow_back and _try_press_back(ctx):
        page = _probe_page(ctx)
        if _is_navigable(page, target):
            _log.info('[OPS] 出逃①成功: 返回箭头后识别为 {}，可重新规划', page)
            if page is not None:
                _adopt_page(ctx, page)
            return page
        _log.warning('[OPS] 出逃①: 返回箭头后仍不可导航 (当前: {})', page or '未知')

    if ctx.stop_event.is_set():
        raise TaskStopRequested('出逃')

    # ② 清弹窗：确认弹窗 / 网络重连 / 整屏结果页会同时糊掉识别器和 checker。
    if (
        _try_dismiss_popup(ctx)
        or _try_dismiss_result_overlay(ctx)
        or _try_dismiss_network_error(ctx)
    ):
        page = _probe_page(ctx)
        if _is_navigable(page, target):
            _log.info('[OPS] 出逃②成功: 清弹窗后识别为 {}，可重新规划', page)
            if page is not None:
                _adopt_page(ctx, page)
            return page
        _log.warning('[OPS] 出逃②: 清弹窗后仍不可导航 (当前: {})', page or '未知')

    if ctx.stop_event.is_set():
        raise TaskStopRequested('出逃')

    # ③ 退避：给加载 / 动画一个完整窗口后重识别。
    time.sleep(ESCAPE_BACKOFF)
    page = _probe_page(ctx)
    if _is_navigable(page, target):
        _log.info(
            '[OPS] 出逃③成功: 退避 {:.1f}s 后识别为 {}，可重新规划',
            ESCAPE_BACKOFF,
            page,
        )
        if page is not None:
            _adopt_page(ctx, page)
        return page

    _log.error(
        '[OPS] 出逃失败: 三级阶梯用尽仍无法恢复到可导航页面 (当前: {})',
        page or '未知',
    )
    return None


def ensure_page(
    ctx: GameContext,
    target: str,
    *,
    max_escapes: int = MAX_ESCAPE_ATTEMPTS,
) -> None:
    """确保到达目标页面；UNKNOWN / 孤岛页先出逃，再重新规划。

    与旧的 ``goto_page`` 相比，UNKNOWN 不再是一抛了之的终点：

    1. ``_goto_page`` 识别失败 (PageNotRecognizedError) 或 BFS 判定不可达
       (孤岛页 / 目标无入边) 时，进入 :func:`escape`；
    2. 出逃阶梯按「返回箭头 → 清弹窗 → 退避」执行，出逃成功后重置 UIStack；
    3. 下一轮重新识别当前页、重新跑 BFS，而不是沿用失败前的路径；
    4. 最多 ``max_escapes`` 次 (默认 :data:`MAX_ESCAPE_ATTEMPTS` = 3)，
       用尽即抛带「预算耗尽」的明确错误，绝不无限重试。

    看门狗 (批次 4.6) 与上述出逃合并为**一套恢复逻辑**：看门狗在
    :func:`_goto_page` 内发现「同页同动作 3 次 / 同页 12 步 / 连败 5 次 /
    12 步未达目标」时抛 :class:`PageDriftError`，``ensure_page`` 不再用出逃
    掩盖它，而是直接上抛带页面轨迹的错误。出逃阶梯本身的动作不计入
    看门狗；但看门狗跨出逃重试复用，出逃后仍反复打转会被 12 步规则捕获。

    刻意**不做**的两件事:

    - **不重启游戏**。``restart_game`` 是几十秒的重手段, 由任务层按轮次决定,
      塞进导航里会导致"卡一次就重启"的风暴。
    - **不做无限重试**。恢复预算有硬上界，失败要快，不要把一次导航拖成几分钟。

    Parameters
    ----------
    ctx:
        游戏上下文。
    target:
        目标页面名 (:class:`PageName` 或等价字符串)。
    max_escapes:
        出逃重规划预算。``0`` 表示不恢复，直接执行一次原始导航。

    Raises
    ------
    PageDriftError
        看门狗判定页面漂移/导航卡死；错误携带最近页面/动作轨迹。
    PageNotRecognizedError
        UNKNOWN 状态下恢复预算耗尽；错误信息带目标页与最近一次原因。
    NavigationError
        孤岛页 / 不可达 / 走不过去，且恢复预算耗尽。
    TaskStopRequested
        用户请求停止。
    """
    budget = max(0, int(max_escapes))
    escapes_used = 0
    last_error: NavigationError | None = None
    # 单一看门狗跨出逃重试复用：出逃内部动作不记步，但每次重新规划的
    # BFS 点击会继续累计，避免「出逃→原地→再出逃」把预算耗成一团乱麻。
    watchdog = _NavWatchdog(_page_label(target))

    while True:
        if ctx.stop_event.is_set():
            raise TaskStopRequested('导航')

        try:
            _goto_page(ctx, target, watchdog=watchdog)
            if escapes_used:
                _log.info(
                    '[OPS] 出逃重规划后到达目标页面: {} (出逃 {} 次)',
                    target,
                    escapes_used,
                )
            return
        except TaskStopRequested:
            raise
        except PageDriftError:
            # 看门狗只负责「发现漂移」。已知页面卡死不是 UNKNOWN/孤岛，
            # 不点返回箭头、也不吞成通用 NavigationError，直接上抛带轨迹错误。
            raise
        except NavigationError as error:
            last_error = error
            unknown = isinstance(error, PageNotRecognizedError)
            unreachable = isinstance(error, _UnreachablePageError)
            if unknown or unreachable:
                _log.warning(
                    '[OPS] 检测到未知/孤岛页面，尝试出逃 ({}/{}): {}',
                    escapes_used,
                    budget,
                    error,
                )
            else:
                _log.warning(
                    '[OPS] 导航失败，尝试恢复出逃 ({}/{}): {}',
                    escapes_used,
                    budget,
                    error,
                )

            if escapes_used >= budget:
                break

            if ctx.stop_event.is_set():
                raise TaskStopRequested('导航恢复')

            escapes_used += 1
            page = escape(
                ctx,
                target,
                reason=str(error),
                # 已知页面走不过去时回退只会更乱；只有 UNKNOWN / 孤岛页才点返回箭头。
                allow_back=unknown or unreachable,
            )
            if page is None:
                _log.warning(
                    '[OPS] 出逃重规划 {}/{}: 仍未恢复到可导航页面，继续消耗预算',
                    escapes_used,
                    budget,
                )
            else:
                _log.info(
                    '[OPS] 出逃重规划 {}/{}: 当前页面 {}，重新执行 BFS 路径规划',
                    escapes_used,
                    budget,
                    page,
                )

    assert last_error is not None  # noqa: S101 - 循环只有在捕获异常后才会 break
    msg = (
        f'导航恢复预算耗尽: 已出逃重规划 {budget} 次仍未到达 "{target}"，'
        f'最近错误: {last_error}'
    )
    _log.error('[OPS] {}', msg)
    screen = _safe_screenshot(ctx)
    if isinstance(last_error, PageNotRecognizedError):
        raise PageNotRecognizedError(msg, screen=screen) from last_error
    raise NavigationError(msg, screen=screen) from last_error


def goto_page(ctx: GameContext, target: str) -> None:
    """兼容别名，等价于 :func:`ensure_page`。

    保留旧名字是为了不破坏外部调用方；新代码请直接用 ``ensure_page``。
    """
    ensure_page(ctx, target)
